import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"プラグイン","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/plugins.md","filePath":"ja-JP/user-guide/settings/plugins.md","lastUpdated":1785993908000}'),n={name:"ja-JP/user-guide/settings/plugins.md"};function o(i,a,p,l,d,h){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="プラグイン" tabindex="-1">プラグイン <a class="header-anchor" href="#プラグイン" aria-label="Permalink to &quot;プラグイン&quot;">​</a></h1><p>インストール済みのすべてのプラグインを一覧表示し、現在読み込まれているプラグイン SDK のバージョンをページヘッダーにバッジとして表示します。クリックすると<a href="./../../dev-guide/">開発者ガイド</a>が開きます。このバージョン番号は、まさにガイドと照らし合わせるためのものです。</p><p>ページは左右2つのペインに分かれています。左がインストール済みのプラグイン、右が選択中のプラグインの詳細です。2つは別々にスクロールするため、長いプラグイン一覧と長い設定フォームが互いを引きずることはありません。</p><p>プラグインが1つもインストールされていない場合、代わりに空の状態メッセージが表示されます。</p><h2 id="プラグイン一覧" tabindex="-1">プラグイン一覧 <a class="header-anchor" href="#プラグイン一覧" aria-label="Permalink to &quot;プラグイン一覧&quot;">​</a></h2><p>インストール済みのプラグインごとに1行、名前とその下にバージョンが表示されます。行を選択すると、そのプラグインが右のペインに開きます。</p><p>一覧は操作できるものから並びます。まず独自の設定を持つプラグイン、次に切り替えられるコンポーネントを持つもの、最後にそれ以外。各グループ内は名前順です。</p><h2 id="選択中のプラグイン" tabindex="-1">選択中のプラグイン <a class="header-anchor" href="#選択中のプラグイン" aria-label="Permalink to &quot;選択中のプラグイン&quot;">​</a></h2><p>ペインの先頭には、プラグインのアイコン、名前、<strong>全体的な機能の説明</strong> が表示されます。</p><p>その下に、独自の設定(単純な有効/無効を超えたカスタム設定)を公開しているプラグインであれば <strong>詳細</strong> と <strong>設定</strong> の2つのタブが表示されます。設定が何もないプラグインにはタブ自体が表示されず、ペイン全体がその詳細になります。</p><h3 id="詳細" tabindex="-1">詳細 <a class="header-anchor" href="#詳細" aria-label="Permalink to &quot;詳細&quot;">​</a></h3><p>このプラグインが登録するコンポーネントが、種類(検索プロバイダー、動的メニュープロバイダーなど)ごとにグループ化されて表示されます。切り替え可能な各コンポーネントには専用の <strong>有効/無効チェックボックス</strong> があります。必須とマークされたコンポーネントは代わりに鍵アイコンが表示され、オフにできません。コンポーネントの横の <strong>(!)</strong> にカーソルを合わせると、詳細な機能の説明が表示されます。</p><p>グループ(またはプラグイン全体)に切り替え可能なコンポーネントが2つ以上ある場合、そのヘッダーの横に <strong>すべて選択/すべて選択解除</strong> リンクが表示され、そのスコープ内のすべてのチェックボックスを1つずつではなく一括で切り替えられます。</p><h3 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h3><p>プラグイン独自の設定を、別のダイアログではなくこの場で編集します。設定を2つ以上のグループに分けているプラグインには、グループごとに1つ、専用のタブ列が追加されます。</p><p><strong>OK</strong> を押すまで何も書き込まれません。このタブを離れる(詳細に戻る、または別のプラグインを選ぶ)と、各項目は保存済みの値に戻ります。放置した編集が後から誤って確定されることはありません。</p><p>プラグインの設定が実際にどのようなものかの具体例(トリガーキーワードの変更など)については、<a href="./../instant-answers.html">インスタントアンサーとキーワードショートカット</a>を参照してください。</p>',17)])])}const c=t(n,[["render",o]]);export{u as __pageData,c as default};
